32	// DESIGN §4's legacy table, in full — the left column is every spelling any fielded
33	// engine has written, the right is what a reader must see today.
34	test('every legacy spelling decodes straight to its canonical status', () => {
35	  for (const [legacy, canonical] of [
36	    [LEGACY_BLOCKED, STATUS_BLOCKED],
37	    [LEGACY_READY, STATUS_READY],
38	    [LEGACY_EXECUTING, STATUS_RUNNING_EXECUTOR],
39	    [LEGACY_AGENT, STATUS_RUNNING_AGENT],
40	    [LEGACY_TASK_DONE, STATUS_DONE], [OUTCOME_DONE, STATUS_DONE],
41	    [LEGACY_TASK_OBSOLETE, STATUS_REJECTED], [OUTCOME_OBSOLETE, STATUS_REJECTED],
42	  ]) {
43	    assert.equal(statusOf(item(legacy)), canonical, `${legacy} should read as ${canonical}`);
44	  }
45	});
