82	// as PARKED — reading it as ready would hand an executor an item a human owns.
83	test('a park outranks any state label standing beside it', () => {
84	  assert.equal(statusOf(item(READY, NEEDS_HUMAN, NEEDS_HUMAN_ACTION)), STATUS_NEEDS_HUMAN_ACTION);
