3	// A `node <path>` written in a doc is a command an agent will run, and nothing
4	// opens it until one does. A link has `deadLinks`; a check's `doc:` field is
5	// grepped by hand; a runnable command in prose had neither, which is how both of
6	// the tasks pack's operational documents spent two months telling every unattended
7	// session to run `<engine>/scheduler/…` after #1326 moved that code to
8	// `packs/claudinite-tasks/` (#1475). The docs are the entire stored prompt of a
9	// member's routine endpoints, so the first instruction each session receives named
10	// a path that resolves nowhere.
11	//
12	// WHAT IT CAN JUDGE. Only paths the corpus owns. A pack's prose legitimately names
13	// files in the *consuming* repo (`node tools/build.mjs`), which cannot exist here,
14	// so two shapes are checkable and the rest is skipped:
15	//
16	//   1. PLACEHOLDER-ROOTED (`node <engine>/hooks/session-end-command.mjs`) — whatever
17	//      the placeholder turns out to mean, the remainder is a real path suffix or the
18	//      command names nothing. This is the shape that broke: the placeholder's own
19	//      definition drifted, and the suffix went with it.
20	//   2. MOUNT-ROOTED (`node .claudinite/shared/packs/…`) — the mount mirrors the
21	//      canon, so the path below it resolves against this tree directly.
22	//
23	// A bare filename (`node worker.mjs`, run from a task directory) and a plain
24	// relative path are the consuming repo's business and are left alone.
25	const COMMAND = /\bnode\s+((?:<[a-z-]+>|[\w.@/-])[\w.@/<>-]*\.mjs)\b/g;
26	const MOUNT = /^\.claudinite\/shared\//;
27	const PLACEHOLDER = /^<[a-z-]+>\//;
28	
29	// Only the pack docs this repo AUTHORS. The vendored copy under
30	// `.claudinite/shared/packs/` is canon output a member may never edit, so a finding
31	// there is one its owner cannot act on.
32	const AUTHORED_DOC = /^(\.claudinite\/local\/)?packs\/.+\.md$/;
33	
34	const rule = {
35	  id: 'runnable-doc-commands',
36	  severity: 'blocking',
37	  description: 'Every `node <path>` a pack doc tells an agent to run names a file this repo carries',
38	  doc: 'packs/basics/README.md',
39	  why: 'a command in prose is opened only when an agent runs it, so a path left behind by a move goes on instructing every session that follows the doc, with nothing red anywhere',
40	
41	  run(ctx) {
42	    const out = [];
43	    // Suffix matching needs the whole tracked set, not just this doc's neighbours:
44	    // a mount path and a canon path are the same file reached two ways.
45	    const paths = ctx.files;
46	    const resolves = (suffix) => paths.some((f) => f === suffix || f.endsWith(`/${suffix}`));
47	
48	    for (const file of ctx.files.filter((f) => AUTHORED_DOC.test(f))) {
49	      const text = ctx.read(file);
50	      if (text === null) continue;
51	      for (const [, path] of text.matchAll(COMMAND)) {
52	        if (PLACEHOLDER.test(path)) {
53	          const suffix = path.replace(PLACEHOLDER, '');
54	          if (resolves(suffix)) continue;
55	          out.push(finding(rule, {
56	            file,
57	            what: `tells an agent to run \`node ${path}\`, and no file in this repo ends with \`${suffix}\``,
58	            fix: `point the command at the file that owns that code now — and prefer a base the doc can derive from its own location, so the next move cannot silently orphan it again`,
59	          }));
60	        } else if (MOUNT.test(path)) {
61	          const inCanon = path.replace(MOUNT, '');
62	          if (ctx.exists(path) || ctx.exists(inCanon)) continue;
63	          out.push(finding(rule, {
64	            file,
65	            what: `tells an agent to run \`node ${path}\`, which the mount does not carry`,
66	            fix: `name the module that does the job now; a mount path is vendored canon, so \`${inCanon}\` is where it must exist`,
67	          }));
68	        }
69	      }
70	    }
71	    return out;
72	  },
73	};
74	
75	export default rule;

66	  } });
67	  try {
68	    const findings = run(root);
69	    assert.equal(findings.length, 1);
70	    assert.equal(findings[0].file, '.claudinite/local/packs/mine/runbook.md');
71	  } finally { cleanup(root); }
72	});
