74	// A fixture spelling the rule back at itself proves only the matching. The corpus
75	// is the tree this rule exists to keep honest, and it is the one that can disagree.
76	test('runnable-doc-commands: the canon\'s own pack docs are clean', () => {
77	  assert.deepEqual(run(CANON).map((f) => `${f.file}: ${f.what}`), []);
78	});
